public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String[] words = line.split(" ");
        int n = words.length;

        // lengths array
        int[] len = new int[n];
        for (int i = 0; i < n; i++) {
            len[i] = words[i].length();
        }

        // prefix sums
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + len[i];
        }

        // target lengths: 5,7,5,7,7
        int[] targets = {5, 7, 5, 7, 7};

        // We need to find start index s such that there exist indices
        // s = i0 < i1 < i2 < i3 < i4 < i5 = e+1 with segment lengths matching targets
        // Segment 1: words i0..i1-1 total length 5
        // Segment 2: words i1..i2-1 total length 7
        // Segment 3: words i2..i3-1 total length 5
        // Segment 4: words i3..i4-1 total length 7
        // Segment 5: words i4..i5-1 total length 7

        // For each possible start index, try to greedily match segments
        for (int start = 0; start < n; start++) {
            int cur = start;
            boolean ok = true;
            int[] indices = new int[6];
            indices[0] = start;
            for (int seg = 0; seg < 5; seg++) {
                int target = targets[seg];
                // find minimal end index such that sum from cur to end-1 = target
                int lo = cur, hi = n;
                int found = -1;
                while (lo <= hi) {
                    int mid = (lo + hi) / 2;
                    int sum = pref[mid] - pref[cur];
                    if (sum == target) {
                        found = mid;
                        break;
                    } else if (sum < target) {
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }
                if (found == -1) {
                    ok = false;
                    break;
                }
                indices[seg + 1] = found;
                cur = found;
            }
            if (ok) {
                // output the phrase
                StringBuilder sb = new StringBuilder();
                for (int seg = 0; seg < 5; seg++) {
                    if (seg > 0) sb.append(" ");
                    for (int w = indices[seg]; w < indices[seg + 1]; w++) {
                        if (w > indices[seg]) sb.append(" ");
                        sb.append(words[w]);
                    }
                }
                System.out.println(sb.toString());
                return;
            }
        }
        // If no valid phrase found, output nothing (should not happen per problem statement)
    }
}

