            while (section < 5 && idx < n) {
                int wlen = words.get(idx).length();
                count += wlen;
                sections.get(section).add(words.get(idx));
                idx++;
                if (count == targets[section]) {
                    section++;
                    count = 0;
                } else if (count > targets[section]) {
                    valid = false;
                    break;
                }
            }

            if (valid && section == 5) {
                // Found it, print the sections
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < 5; i++) {
                    if (i > 0) sb.append("\n");
                    sb.append(String.join(" ", sections.get(i)));
                }
                System.out.println(sb.toString());
                return;
            }
        }
    }
